char* rpm_get_component(const char *filename, const char *rootdir_or_NULL) /* <=== rpm_get_component */ 
{
    char *ret = NULL;
    char *srpm = NULL;
    rpmts ts;
    rpmdbMatchIterator iter;
    Header header;

    ts = rpmtsCreate();
    /* This loop executes once (normally) or twice (if we detect chroot) */
    while (1)
    {
        iter = rpmtsInitIterator(ts, RPMTAG_BASENAMES, filename, 0);
        header = rpmdbNextIterator(iter);
        //log("%s: header('%s'):%p", __func__, filename, header);
        if (header)
            break;

        if (!rootdir_or_NULL)
            goto error;
        unsigned len = strlen(rootdir_or_NULL);
        if (strncmp(filename, rootdir_or_NULL, len) != 0 || filename[len] != '/')
            goto error;

        /* It is a chroot */
        //log("%s: skipping '%s' pfx", __func__, rootdir_or_NULL);
        rpmdbFreeIterator(iter);
        rpmtsFree(ts);
        ts = rpmtsCreate();
        if (rpmtsSetRootDir(ts, rootdir_or_NULL) != 0)
            goto error1;
        filename += len;
        rootdir_or_NULL = NULL;
    }

    const char *errmsg = NULL;
    srpm = headerFormat(header, "%{SOURCERPM}", &errmsg);
    if (!srpm && errmsg)
    {
        error_msg("cannot get srpm. reason: %s", errmsg);
        goto error;
    }

    ret = get_package_name_from_NVR_or_NULL(srpm);
    free(srpm);

 error:
    rpmdbFreeIterator(iter);
 error1:
    rpmtsFree(ts);
    return ret;
}

static char *get_argv1_if_full_path(const char* cmdline) /* <=== get_argv1_if_full_path */ 
{
    const char *argv1 = strchr(cmdline, ' ');
    while (argv1 != NULL)
    {
        /* we found space in cmdline, so it might contain
         * path to some script like:
         * /usr/bin/python [-XXX] /usr/bin/system-control-network
         */
        argv1++; /* skip the space */
        if (*argv1 != '-')
            break;
        /* looks like -XXX in "perl -XXX /usr/bin/script.pl", skipping */
        argv1 = strchr(argv1, ' ');
    }

    /* if the string following the space doesn't start
     * with '/', it is not a full path to script
     * and we can't use it to determine the package name
     */
    if (argv1 == NULL || *argv1 != '/')
        return NULL;

    /* good, it has "/foo/bar" form, return it */
    int len = strchrnul(argv1, ' ') - argv1;
    return xstrndup(argv1, len);
}

static bool is_path_blacklisted(const char *path) /* <=== is_path_blacklisted */ 
{
    GList *li;
    for (li = settings_setBlackListedPaths; li != NULL; li = g_list_next(li))
    {
        if (fnmatch((char*)li->data, path, /*flags:*/ 0) == 0)
        {
            return true;
        }
    }
    return false;
}

